const SHIP = 'X';

const getPositionString = (row, col) => `${row}, ${col}`;
const directions = [
    [0, 1],
    [1, 0],
    [0, -1],
    [-1, 0],
];

const isInBounds = (board, row, col) => {
    const numRows = board.length;
    const numCols = board[0].length;

    const rowInBounds = row >= 0 && row < numRows;
    const colInBounds = col >= 0 && col < numCols;

    return rowInBounds && colInBounds;
};

// CONTRACT for markShipAsVisited(board, row, col, visited):
//     when this call returns, if the cell at `row`,`col` is part of a
//     ship, that cell and every connected cell of the same ship is in
//     the visited set. (Water or out-of-bounds cells change nothing.)
const markShipAsVisited = (board, row, col, visited) => {
    // Base cases
    if (!isInBounds(board, row, col)) return;

    const curPositionString = getPositionString(row, col);
    if (visited.has(curPositionString)) return;

    if (board[row][col] !== SHIP) return;

    // Process node
    visited.add(curPositionString);

    // Recurse on potential neighbors
    for (const direction of directions) {
        const [rowChange, colChange] = direction;

        const newRow = row + rowChange;
        const newCol = col + colChange;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, the neighbor cell (if it
        // is part of the ship) and every ship cell connected to it is
        // in visited. Trust it, do not trace it. This function already
        // put `row`,`col` into visited, and each neighbor's contract
        // covers the rest of the ship — together, that is this
        // function's full contract, kept.
        markShipAsVisited(board, newRow, newCol, visited);
    }
};

const countBattleships = (board) => {
    const numRows = board.length;
    const numCols = board[0].length;

    let numBattleships = 0;
    const visited = new Set();

    for (let row = 0; row < numRows; row++) {
        for (let col = 0; col < numCols; col++) {
            const curPositionString = getPositionString(row, col);

            if (visited.has(curPositionString)) continue;

            const cellType = board[row][col];
            if (cellType !== SHIP) continue;

            // An unvisited 'X' cell must be the start of a brand new ship,
            // because we already marked every cell of the ships we found.
            numBattleships++;

            // The recursive leap of faith: trust the contract. When this
            // call returns, every cell of this newly found ship is in
            // visited, so the loops can never count the same ship again.
            // We do not trace inside; we just count the ship and move on.
            markShipAsVisited(board, row, col, visited);
        }
    }

    return numBattleships;
};

const buildGraph = (bombs) => {
    const graph = {};

    for (let bomb = 0; bomb < bombs.length; bomb++) {
        graph[bomb] = [];
    }

    for (let bomb = 0; bomb < bombs.length; bomb++) {
        const [bombX, bombY, bombRadius] = bombs[bomb];

        for (let otherBomb = 0; otherBomb < bombs.length; otherBomb++) {
            if (otherBomb === bomb) continue;

            const [otherBombX, otherBombY] = bombs[otherBomb];

            const xDistance = bombX - otherBombX;
            const yDistance = bombY - otherBombY;

            // Compare squared distances so we never need a square root.
            const squaredDistance = xDistance * xDistance + yDistance * yDistance;
            const squaredRadius = bombRadius * bombRadius;

            // This graph is DIRECTED: a bomb with a big radius can set off
            // a bomb with a small radius without the reverse being true.
            const canDetonateOtherBomb = squaredDistance <= squaredRadius;
            if (!canDetonateOtherBomb) continue;

            graph[bomb].push(otherBomb);
        }
    }

    return graph;
};

// CONTRACT for markDetonatedBombs(graph, bomb, visited):
//     when this call returns, `bomb` and every bomb reachable from
//     `bomb` through the chain reaction is in the visited set.
const markDetonatedBombs = (graph, bomb, visited) => {
    // Base case
    if (visited.has(bomb)) return;

    // Process node
    visited.add(bomb);

    // Recurse on neighbors
    const neighbors = graph[bomb];

    for (const neighbor of neighbors) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, `neighbor` and every
        // bomb reachable from it is in visited. Trust it, do not trace
        // it. This function already put `bomb` into visited, and each
        // neighbor's contract covers every bomb its explosion can
        // reach — together, that is this function's full contract,
        // kept.
        markDetonatedBombs(graph, neighbor, visited);
    }
};

const maximumDetonation = (bombs) => {
    const graph = buildGraph(bombs);

    let maxDetonatedBombs = 0;

    for (let startBomb = 0; startBomb < bombs.length; startBomb++) {
        // Each starting bomb gets a fresh visited set because we are
        // measuring each chain reaction separately.
        const visited = new Set();

        // The recursive leap of faith: trust the contract. When this
        // call returns, `startBomb` and every bomb its chain reaction
        // sets off is in visited. We do not trace inside; we just read
        // visited.size to see how many bombs exploded.
        markDetonatedBombs(graph, startBomb, visited);

        maxDetonatedBombs = Math.max(maxDetonatedBombs, visited.size);
    }

    return maxDetonatedBombs;
};

const START_ROOM = 0;

// CONTRACT for visitRooms(rooms, curRoom, visited):
//     when this call returns, `curRoom` and every room whose door we
//     can eventually open starting from `curRoom` is in the visited set.
const visitRooms = (rooms, curRoom, visited) => {
    // Base case
    // Two different rooms can hold keys to the same room, so we could
    // see a room twice. We track visited rooms to avoid infinite loops.
    if (visited.has(curRoom)) return;

    // Process node
    visited.add(curRoom);

    // Recurse on neighbors
    const keysInRoom = rooms[curRoom];

    for (const key of keysInRoom) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, the room this key opens
        // and every room reachable from it is in visited. Trust it, do
        // not trace it. This function already put `curRoom` into
        // visited, and each key's contract covers all the rooms behind
        // it — together, that is this function's full contract, kept.
        visitRooms(rooms, key, visited);
    }
};

const canVisitAllRooms = (rooms) => {
    const visited = new Set();

    // The recursive leap of faith: trust the contract. When this
    // call returns, room 0 and every room we can possibly enter is
    // in visited. We do not trace inside; we just compare
    // visited.size to the total number of rooms.
    visitRooms(rooms, START_ROOM, visited);

    // We succeed only if every single room was reachable from room 0.
    return visited.size === rooms.length;
};

const NO_MANAGER = -1;

const buildGraph = (manager) => {
    const graph = {};

    for (let employee = 0; employee < manager.length; employee++) {
        const employeeManager = manager[employee];

        // The head of the company has no manager.
        if (employeeManager === NO_MANAGER) continue;

        const managerInGraph = graph.hasOwnProperty(employeeManager);
        if (!managerInGraph) graph[employeeManager] = [];

        graph[employeeManager].push(employee);
    }

    return graph;
};

// CONTRACT for getTimeToInformSubtree(graph, employee, informTime):
//     returns the number of minutes between the moment `employee`
//     hears the news and the moment every person below `employee`
//     in the tree has heard it.
const getTimeToInformSubtree = (graph, employee, informTime) => {
    // The hierarchy is a tree, so there are no cycles and we do not
    // need a visited set.

    // Base case
    const employeeHasSubordinates = graph.hasOwnProperty(employee);
    if (!employeeHasSubordinates) return 0;

    // Process node
    let maxTimeToInformSubordinateSubtree = 0;

    // Recurse on neighbors
    const subordinates = graph[employee];

    for (const subordinate of subordinates) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — it returns how long the news takes to
        // reach everyone below `subordinate`. Trust it, do not trace
        // it. Our own inform time plus the slowest subordinate's
        // guaranteed time is exactly this function's contract, kept.
        const timeToInformSubordinateSubtree = getTimeToInformSubtree(
            graph,
            subordinate,
            informTime,
        );

        // All subordinates hear the news at the same time (in parallel),
        // so we only wait for the SLOWEST branch to finish.
        maxTimeToInformSubordinateSubtree = Math.max(
            maxTimeToInformSubordinateSubtree,
            timeToInformSubordinateSubtree,
        );
    }

    return informTime[employee] + maxTimeToInformSubordinateSubtree;
};

const numOfMinutes = (n, headID, manager, informTime) => {
    const graph = buildGraph(manager);

    // The recursive leap of faith: trust the contract. This call
    // returns the minutes needed for the news to travel from the
    // head to every employee in the company. We do not trace
    // inside; we just return that number.
    return getTimeToInformSubtree(graph, headID, informTime);
};

const ROOT_PARENT_ID = 0;

const buildGraph = (pid, ppid) => {
    const graph = {};

    for (let index = 0; index < pid.length; index++) {
        const curProcess = pid[index];
        const parentProcess = ppid[index];

        // The root process has no parent, so it is nobody's child.
        if (parentProcess === ROOT_PARENT_ID) continue;

        const parentInGraph = graph.hasOwnProperty(parentProcess);
        if (!parentInGraph) graph[parentProcess] = [];

        graph[parentProcess].push(curProcess);
    }

    return graph;
};

// CONTRACT for collectKilledProcesses(graph, curProcess, killedProcesses):
//     when this call returns, `curProcess` and every process below it
//     in the tree has been added to the `killedProcesses` list.
const collectKilledProcesses = (graph, curProcess, killedProcesses) => {
    // The processes form a tree, so there are no cycles and we do not
    // need a visited set.

    // Process node
    killedProcesses.push(curProcess);

    // Recurse on neighbors
    // Base case: a process with no children has nothing to recurse on.
    const processHasChildren = graph.hasOwnProperty(curProcess);
    if (!processHasChildren) return;

    const childProcesses = graph[curProcess];

    for (const childProcess of childProcesses) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, `childProcess` and
        // every process below it has been added to the list. Trust it,
        // do not trace it. This function already added `curProcess`,
        // and each child's contract covers its whole subtree —
        // together, that is this function's full contract, kept.
        collectKilledProcesses(graph, childProcess, killedProcesses);
    }
};

const killProcess = (pid, ppid, kill) => {
    const graph = buildGraph(pid, ppid);

    const killedProcesses = [];

    // The recursive leap of faith: trust the contract. When this
    // call returns, `kill` and every process underneath it is in
    // the killedProcesses list. We do not trace inside; we just
    // return the list.
    collectKilledProcesses(graph, kill, killedProcesses);

    return killedProcesses;
};

const START_TIME = 0;

const buildGraph = (times) => {
    const graph = {};

    for (const time of times) {
        const [sourceNode, targetNode, travelTime] = time;

        const sourceInGraph = graph.hasOwnProperty(sourceNode);
        if (!sourceInGraph) graph[sourceNode] = [];

        graph[sourceNode].push([targetNode, travelTime]);
    }

    return graph;
};

// CONTRACT for recordArrivalTimes(graph, curNode, curArrivalTime, arrivalTimes):
//     when this call returns, `curNode` and every node reachable from
//     it has an entry in `arrivalTimes` at least as fast as any route
//     that starts by reaching `curNode` at time `curArrivalTime`.
const recordArrivalTimes = (graph, curNode, curArrivalTime, arrivalTimes) => {
    // Base case
    // Instead of a plain visited set, we remember the best-known arrival
    // time for each node. We only continue when we just arrived FASTER
    // than every previous visit, so slower paths get pruned away.
    const nodeHasArrivalTime = arrivalTimes.hasOwnProperty(curNode);
    const bestKnownArrivalTime = nodeHasArrivalTime
        ? arrivalTimes[curNode]
        : Infinity;

    if (curArrivalTime >= bestKnownArrivalTime) return;

    // Process node
    arrivalTimes[curNode] = curArrivalTime;

    // Recurse on neighbors
    const nodeInGraph = graph.hasOwnProperty(curNode);
    if (!nodeInGraph) return;

    const neighbors = graph[curNode];

    for (const neighbor of neighbors) {
        const [neighborNode, travelTime] = neighbor;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, the neighbor and every
        // node past it have arrival times at least as fast as this
        // route offers. Trust it, do not trace it. This function
        // already recorded `curNode`'s time, and each neighbor's
        // contract covers the rest — together, that is this function's
        // full contract, kept.
        recordArrivalTimes(
            graph,
            neighborNode,
            curArrivalTime + travelTime,
            arrivalTimes,
        );
    }
};

const networkDelayTime = (times, n, k) => {
    const graph = buildGraph(times);

    const arrivalTimes = {};

    // The recursive leap of faith: trust the contract. When this
    // call returns, every node the signal can reach from node `k`
    // has its fastest arrival time recorded in arrivalTimes. We do
    // not trace inside; we just scan those times for the largest
    // one.
    recordArrivalTimes(graph, k, START_TIME, arrivalTimes);

    // The whole network is covered once the LAST node hears the signal,
    // so the answer is the largest arrival time.
    let maxArrivalTime = 0;

    for (let node = 1; node <= n; node++) {
        const nodeWasReached = arrivalTimes.hasOwnProperty(node);
        if (!nodeWasReached) return -1;

        maxArrivalTime = Math.max(maxArrivalTime, arrivalTimes[node]);
    }

    return maxArrivalTime;
};

const buildGraph = (edges) => {
    const graph = {};

    for (const edge of edges) {
        const [nodeOne, nodeTwo] = edge;

        const nodeOneInGraph = graph.hasOwnProperty(nodeOne);
        const nodeTwoInGraph = graph.hasOwnProperty(nodeTwo);

        if (!nodeOneInGraph) graph[nodeOne] = [];
        if (!nodeTwoInGraph) graph[nodeTwo] = [];

        graph[nodeOne].push(nodeTwo);
        graph[nodeTwo].push(nodeOne);
    }

    return graph;
};

// CONTRACT for canReachDestination(graph, curNode, destination, visited):
//     returns true if there is a path from `curNode` to `destination`
//     that avoids the nodes already in the visited set, and false
//     otherwise.
const canReachDestination = (graph, curNode, destination, visited) => {
    // Base cases
    if (curNode === destination) return true;

    // This is an undirected graph, so it can have cycles. We track
    // visited nodes so we never walk in circles forever.
    if (visited.has(curNode)) return false;

    // Process node
    visited.add(curNode);

    // Recurse on neighbors
    const nodeInGraph = graph.hasOwnProperty(curNode);
    if (!nodeInGraph) return false;

    const neighbors = graph[curNode];

    for (const neighbor of neighbors) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — it returns true exactly when
        // `destination` can be reached from this neighbor. Trust it,
        // do not trace it. If any neighbor can reach the destination,
        // then so can `curNode` — which is exactly this function's
        // contract, kept.
        const pathExistsThroughNeighbor = canReachDestination(
            graph,
            neighbor,
            destination,
            visited,
        );

        if (pathExistsThroughNeighbor) return true;
    }

    return false;
};

const validPath = (n, edges, source, destination) => {
    const graph = buildGraph(edges);

    const visited = new Set();

    // The recursive leap of faith: trust the contract. This call
    // returns true exactly when some path leads from `source` to
    // `destination`. We do not trace inside; we just return its
    // answer.
    return canReachDestination(graph, source, destination, visited);
};
